// Block (composition) — linked third-party identities with connect and disconnect actions.
// Card, Badge, Button, and Separator own look; Stack owns arrangement.
import { Fragment } from "react";
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./ConnectedAccounts.css";

export interface ConnectedAccountsProps {
  accounts: {
    id: string;
    provider: string;
    email?: string;
    connected?: boolean;
  }[];
  onConnect?: (id: string) => void;
  onDisconnect?: (id: string) => void;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function ConnectedAccounts({
  accounts,
  onConnect,
  onDisconnect,
  className,
  ref,
}: ConnectedAccountsProps) {
  return (
    <Card
      ref={ref}
      role="region"
      aria-label="Connected accounts"
      className={className ? `sd-connectedaccounts ${className}` : "sd-connectedaccounts"}
    >
      <Stack gap="small" className="sd-connectedaccounts__list">
        {accounts.map((account, index) => (
          <Fragment key={account.id}>
            {index > 0 && <Separator />}
            <Stack
              direction="row"
              justify="between"
              align="center"
              gap="small"
              className="sd-connectedaccounts__row"
            >
              <Stack gap="x-small" className="sd-connectedaccounts__details">
                <Stack direction="row" align="center" gap="x-small" wrap className="sd-connectedaccounts__head">
                  <>
                    <span className="sd-connectedaccounts__provider sd-type-body-medium">
                      {account.provider}
                    </span>
                  </>
                  {account.connected && <Badge>Connected</Badge>}
                </Stack>
                {account.email && (
                  <>
                    <span className="sd-connectedaccounts__email sd-type-caption-medium">
                      {account.email}
                    </span>
                  </>
                )}
              </Stack>
              {account.connected ? (
                <Button
                  type="button"
                  variant="secondary"
                  size="small"
                  onPress={() => onDisconnect?.(account.id)}
                >
                  Disconnect
                </Button>
              ) : (
                <Button type="button" variant="secondary" size="small" onPress={() => onConnect?.(account.id)}>
                  Connect
                </Button>
              )}
            </Stack>
          </Fragment>
        ))}
      </Stack>
    </Card>
  );
}

/* ConnectedAccounts.css — arrangement only; composed Components own all visual treatment. */
.sd-connectedaccounts {
  width: 100%;
}

.sd-connectedaccounts__row,
.sd-connectedaccounts__details {
  min-width: 0;
}

.sd-connectedaccounts__email {
  color: var(--sd-color-text-muted);
}
